def test_build_embedding_text_doc():
    chunk = {
        "type": "doc",
        "source": "docs/readme.md",
        "method": "Introduction",
        "content": "Hello world",
    }
    expected = "Documentation: docs/readme.md\nSection: Introduction\n\nHello world"
    assert m.build_embedding_text(chunk) == expected


def test_build_embedding_text_php():
    chunk = {
        "type": "function",
        "source": "src/app.php",
        "namespace": "App",
        "class_kind": "class",
        "class": "User",
        "method": "getName",
        "calls": [{"object": "self", "method": "fetch"}],
        "parameter_types": {"name": "string"},
        "assignments": [{"left": "$this->id", "right": "1"}],
        "content": "return $name;",
    }
    text = m.build_embedding_text(chunk)
    assert "File: src/app.php" in text
    assert "Namespace: App" in text
    assert "Class: User" in text
    assert "Method: getName" in text
    assert "self fetch" in text
    assert "name string" in text
    assert "$this->id 1" in text
    assert "return $name;" in text


def test_build_metadata_php():
    chunk = {
        "source": "src/app.php",
        "filename": "app.php",
        "language": "php",
        "namespace": "App",
        "class": "User",
        "class_kind": "class",
        "method": "getName",
        "type": "function",
        "abstract": False,
        "start_line": 10,
        "end_line": 20,
        "part": 1,
        "parts": 1,
        "calls": [{"object": "self", "method": "fetch"}],
        "parameter_types": {"name": "string"},
        "assignments": [{"left": "$this->id", "right": "1"}],
    }
    meta = m.build_metadata(chunk)
    assert meta["source"] == "src/app.php"
    assert meta["abstract"] is False
    assert meta["start_line"] == 10
    assert meta["calls"] == "self->fetch"
    assert meta["parameter_types"] == "name->string"
    assert meta["assignments"] == "$this->id=1"


def test_markdown_chunks_from_text_simple():
    text = "# Title\n\nSome content here.\n\n## Subtitle\n\nMore content."
    chunks = m.markdown_chunks_from_text(text, "docs/readme.md", "readme.md")
    assert len(chunks) == 2
    assert chunks[0]["method"] == "Title"
    assert chunks[0]["start_line"] == 1
    assert chunks[0]["end_line"] == 4
    assert chunks
